use xiom.io;
fn km_to_miles(km: Float64) -> Float64 {
  return km * 0.621371;
}

fn miles_to_km(miles: Float64) -> Float64 {
  return miles * 1.60934;
}

fn kg_to_lbs(kg: Float64) -> Float64 {
  return kg * 2.20462;
}

fn lbs_to_kg(lbs: Float64) -> Float64 {
  return lbs * 0.453592;
}

fn main() {
  let trip_distance = 42.0;
  let luggage_weight = 23.0;
  let miles = km_to_miles(trip_distance);
  let pounds = kg_to_lbs(luggage_weight);
  io.println("All conversions complete!");
}
